set -euo pipefail
printf '%s' '' | base64 -d | tar -xzf - -C /opt/brigada-core-src
cd /opt/brigada-core-src
./gradlew --no-daemon clean build
install -d -m 0755 /opt/minecraft/resourcepack
printf '%s' '' | base64 -d > /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip
chmod 0644 /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip
printf '%s' '' | base64 -d > /etc/systemd/system/brigada-pack.service
systemctl daemon-reload
systemctl enable --now brigada-pack.service
if command -v ufw >/dev/null 2>&1 && ufw status | grep -q '^Status: active'; then ufw allow 8088/tcp; fi
printf '\nBUILD\n'
sha256sum build/libs/brigada-core-0.1.0.jar
printf '\nPACK\n'
sha1sum /opt/minecraft/resourcepack/Brigada13-26.3-snapshot-9.zip
printf '\nHTTP\n'
curl -fsSI http://127.0.0.1:8088/Brigada13-26.3-snapshot-9.zip | head -n 5
printf '\nSERVICE\n'
systemctl is-active brigada-pack.service
